import { attrs, defaults, isWeb, nonWebGroups, q, slug, unique, wholeLabelWildcard } from './util.js';

const host = (e) => wholeLabelWildcard(e.host);
const addrId = (prefix, h) => `${prefix}_${h.startsWith('*.') ? 'wc_' : ''}${slug(h)}`;

function generate(endpoints, options = {}) {
  const o = defaults(options);
  const label = o.scope ? ` (${o.scope})` : '';
  const srcAddr = o.sourceAddress === 'any' ? 'all' : o.sourceAddress;
  const out = [];
  const policies = [];

  out.push(`# Fortinet FortiGate (FortiOS) policies for Azure Local endpoints${label}
# Generated by azure-local-endpoints. Review before applying.
# FortiGate FQDN objects match domains only, so URL paths are dropped.
terraform {
  required_providers {
    fortios = {
      source  = "fortinetdev/fortios"
      version = ">= 1.20"
    }
  }
}

variable "fortios_hostname" { type = string }
variable "fortios_token" {
  type      = string
  sensitive = true
}

provider "fortios" {
  hostname = var.fortios_hostname
  token    = var.fortios_token
}
`);

  const seen = new Set();
  const addressesFor = (eps) => {
    const hosts = unique(eps.map(host)).sort();
    for (const h of hosts) {
      const id = addrId(o.prefix, h);
      if (seen.has(id)) continue;
      seen.add(id);
      out.push(`resource "fortios_firewall_address" "${id}" {
${attrs(2, [
        ['name', q(`${o.prefix}-${h}`.slice(0, 79))],
        ['type', q(h.startsWith('*.') ? 'wildcard-fqdn' : 'fqdn')],
        ['fqdn', q(h)]
      ])}
}
`);
    }
    return hosts.map((h) => addrId(o.prefix, h));
  };

  const addGroup = (key, title, eps, serviceAttr, portrange) => {
    const members = addressesFor(eps);
    const gid = `${o.prefix}_${key}`;
    out.push(`resource "fortios_firewall_addrgrp" "${gid}" {
  name = ${q(`${o.prefix}-${key.replace(/_/g, '-')}`)}
${members.map((m) => `
  member {
    name = fortios_firewall_address.${m}.name
  }`).join('\n')}
}

resource "fortios_firewallservice_custom" "${gid}" {
${attrs(2, [['name', q(`${o.prefix}-${key.replace(/_/g, '-')}`)], [serviceAttr, q(portrange)]])}
}
`);
    policies.push({ gid, title });
  };

  const web = endpoints.filter(isWeb);
  if (web.length) {
    const ports = unique(web.flatMap((e) => e.ports)).sort((a, b) => a - b).join(' ');
    addGroup('web', 'web', web, 'tcp_portrange', ports);
  }
  for (const g of nonWebGroups(endpoints)) {
    addGroup(`${g.protocol}_${g.port}`, `${g.protocol}/${g.port}`, g.endpoints, `${g.protocol}_portrange`, String(g.port));
  }

  for (const p of policies) {
    out.push(`resource "fortios_firewall_policy" "${p.gid}" {
${attrs(2, [
      ['name', q(`${o.prefix}-allow-${p.title.replace('/', '-')}`.slice(0, 35))],
      ['action', '"accept"'],
      ['schedule', '"always"'],
      ['status', '"enable"'],
      ['logtraffic', '"all"']
    ])}

  srcintf {
    name = ${q(o.sourceZone)}
  }

  dstintf {
    name = ${q(o.destinationZone)}
  }

  srcaddr {
    name = ${q(srcAddr)}
  }

  dstaddr {
    name = fortios_firewall_addrgrp.${p.gid}.name
  }

  service {
    name = fortios_firewallservice_custom.${p.gid}.name
  }
}
`);
  }
  return [{ filename: `${o.prefix}-fortinet.tf`, content: out.join('\n') }];
}

export default {
  id: 'fortinet',
  name: 'Fortinet (FortiGate)',
  description: 'fortinetdev/fortios provider: FQDN addresses, address groups, custom services and policies.',
  generate
};
